    && hasExactKeys(glossary, ["id", "version", "contentDigest"])
    && glossary.id === "korean-prose-core" && glossary.version === "1.2.1"
    && typeof glossary.contentDigest === "string" && DIGEST.test(glossary.contentDigest);
