  return { schemaVersion: SCHEMA_VERSION, mode: "mcp", status: "unavailable", sourceDigest, glossaryId: null, glossaryVersion: null, glossaryDigest: null, matchSetDigest: null, matchCount: 0, warnings: ["GLOSSARY_UNAVAILABLE"] };
