  let output = source;
  for (const edit of [...edits].sort((left, right) => right.start - left.start || right.end - left.end)) {
    output = `${output.slice(0, edit.start)}${edit.replacement}${output.slice(edit.end)}`;
  }
  return output;
}

/** @param {string} source @param {Edit} edit */
